-- public.rank_lacks(p_world uuid, p_founder uuid, p_uid uuid, p_power text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.rank_lacks(p_world uuid, p_founder uuid, p_uid uuid, p_power text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select 'Your rank at ' || d.name || ' (' || r.name || ') cannot ' || p.may_not || '.'
    from deed d
    join deed_member m on m.world_id = d.world_id and m.founder = d.founded_by and m.uid = p_uid
    join deed_rank_def r on r.id = m.rank_id
    join rank_power p on p.id = p_power
   where d.world_id = p_world and d.founded_by = p_founder and r.perms & (1 << p.bit) = 0
$function$
